interface Spec {
  lavoro: string;
  soggetto?: string;
  cliente: number;
  stato: Stato;
  giorniFa: number; // days ago (creation)
  grafici?: number[]; // indexes into the designers list
  rifiuti?: number; // rejected PDFs (revisioniPdf)
  prova?: "non_serve" | "spedita_approvata" | "da_rifare";
  esitoCaduta?: "approvata";
  sospesa?: { motivo: Row<"sospensioni">["motivo"]; nota: string };
  correzioni?: number[]; // minutes
  consegnaFra?: number; // days from now (negative = overdue)
  manuale?: boolean;
  forzata?: boolean;
  wetransfer?: boolean;
  noteInterne?: string;
}

