// ---------------------------------------------------------------
// Generator
// ---------------------------------------------------------------
const HOUR = 3600_000;
const DAY = 24 * HOUR;

// Deterministic PRNG: same data after every reset
function prng(seed: number) {
  let s = seed >>> 0;
  return () => {
    s = (s + 0x6d2b79f5) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const slug = (s: string) =>
  s.normalize("NFKD").replace(/[^A-Za-z0-9]+/g, "_").replace(/^_|_$/g, "").slice(0, 28).toUpperCase();

export function buildSeed(nowMs = Date.now()): Seed {
  const rnd = prng(2026);
  const uid = () => crypto.randomUUID();
  const iso = (ms: number) => new Date(ms).toISOString();
  const db: Seed = {
    clienti: [], commessa_assegnatari: [], commesse: [], correzioni: [], email_inviate: [],
    email_template: [], eventi: [], file_commessa: [], gruppi_prestampa: [], impostazioni: [],
    note_forzatura: [], sospensioni: [], utente_gruppi: [], utenti: [],
  };

  // users + teams
  const gruppoIds = new Map<string, string>();
  for (let i = 1; i <= 5; i++) {
    const nome = `prestampa0${i}`;
    const id = uid();
    gruppoIds.set(nome, id);
    db.gruppi_prestampa.push({ id, nome, mailbox: `${nome}@${DEMO_DOMAIN}` });
  }
  for (const p of PERSONE) {
    const id = uid();
    db.utenti.push({
      id,
      nome: p.nome,
      email: `${p.user}@${DEMO_DOMAIN}`,
      ruolo: p.ruolo,
      attivo: true,
      iniziali: p.nome.split(" ").map((x) => x[0]).join(""),
      creato_il: iso(nowMs - 200 * DAY),
    });
    for (const g of p.gruppi) db.utente_gruppi.push({ utente_id: id, gruppo_id: gruppoIds.get(g)! });
  }
  const userBy = (ruolo: Ruolo) => db.utenti.find((u) => u.ruolo === ruolo)!;
  const respProd = userBy("responsabile_produzione");
  const respGrafico = userBy("responsabile_ufficio_grafico");
  const grafici = db.utenti.filter((u) => u.ruolo === "grafico");
  const mailboxOf = (userId: string) => {
    const g = db.utente_gruppi.find((ug) => ug.utente_id === userId);
    return db.gruppi_prestampa.find((x) => x.id === g?.gruppo_id)?.mailbox ?? `prestampa01@${DEMO_DOMAIN}`;
  };

  // customers
  for (const [i, c] of CLIENTI.entries()) {
    db.clienti.push({
      id: uid(),
      nome: c.nome,
      nome_chiave: c.nome.trim().toLowerCase(),
      email: c.email ?? null,
      telefono: c.telefono ?? null,
      note: c.note ?? null,
      creato_il: iso(nowMs - (180 + i * 7) * DAY),
    });
  }

  // templates
  for (const t of TEMPLATES) {
    db.email_template.push({
      id: uid(),
      ...t,
      ultima_modifica_il: iso(nowMs - 60 * DAY),
      ultima_modifica_da_user_id: respProd.id,
    });
  }

  const render = (tpl: string, c: Row<"commesse">, cliente: string, utente: string) =>
    tpl
      .split("{job_number}").join(c.numero_commessa)
      .split("{job_name}").join(c.nome_lavoro)
      .split("{customer}").join(cliente)
      .split("{user_name}").join(utente);

  const ORDER: Stato[] = [
    "disponibile", "assegnata", "in_lavorazione", "in_attesa_approvazione_pdf",
    "in_attesa_prova_colore", "in_attesa_approvazione_caduta", "in_produzione_matrice", "spedito",
  ];

  SPECS.forEach((spec, idx) => {
    const target = ORDER.indexOf(spec.stato);
    const reached = (s: Stato) => target >= ORDER.indexOf(s);
    const cliente = db.clienti[spec.cliente];
    const stampatore = STAMPATORI[idx % STAMPATORI.length];
    const creata = nowMs - spec.giorniFa * DAY;
    // time moves forward in steps, never past "now"
    let t = creata;
    // shipped jobs complete in ~2 weeks, the others run up to today
    const span = Math.min(Math.max(nowMs - creata - HOUR, HOUR), spec.stato === "spedito" ? 14 * DAY : Infinity);
    const steps = 4 + target * 2 + (spec.rifiuti ?? 0) * 2;
    const tick = () => {
      t += (span / (steps + 2)) * (0.6 + rnd() * 0.8);
      t = Math.min(t, nowMs - 10 * 60_000);
      return iso(t);
    };

    const id = uid();
    const numero = `2026/${String(1040 + idx * 7).padStart(5, "0")}`;
    const codice = slug(spec.soggetto ?? spec.lavoro);
    const assegnati = (spec.grafici ?? []).map((g) => grafici[g % grafici.length]);
    const lead = assegnati[0];

    const c: Row<"commesse"> = {
      id,
      numero_commessa: numero,
      cliente_id: cliente.id,
      nome_lavoro: spec.lavoro,
      soggetto: spec.soggetto ?? null,
      cod_soggetto: spec.soggetto ? `SG-${String(300 + idx * 3)}` : null,
      stampatore: stampatore.nome,
      cod_stampatore: stampatore.cod,
      rif_cliente: `RC-${String(7700 + idx * 13)}`,
      cod_articolo: `ART-${String(51000 + idx * 37)}`,
      numero_ordine: spec.sospesa?.motivo === "attesa_ordine" ? null : `ORD-${String(8800 + idx * 11)}`,
      operatore_repro: lead?.nome ?? null,
      stato: spec.stato,
      sospensione_attiva_id: null,
      presa_in_carico_da_user_id: null,
      presa_in_carico_il: null,
      revisioni_pdf: 0,
      esito_prova_colore: null,
      esito_caduta: null,
      data_consegna_prevista: spec.consegnaFra !== undefined ? iso(nowMs + spec.consegnaFra * DAY) : null,
      termine_primo_pdf: null,
      note_interne: spec.noteInterne ?? null,
      spedita_il: null,
      creata_il: iso(creata),
      aggiornata_il: iso(creata),
      annullata_il: null,
    };

    const ev = (tipo: EventoTipo, titolo: string, data: string, userId?: string | null, dettaglio?: string, ref?: { type: string; id: string }) =>
      db.eventi.push({
        id: uid(), commessa_id: id, data, user_id: userId ?? null, tipo, titolo,
        dettaglio: dettaglio ?? null, ref_type: ref?.type ?? null, ref_id: ref?.id ?? null,
      });

    const file = (nome: string, tipo: Row<"file_commessa">["tipo"], data: string, userId: string) => {
      const f: Row<"file_commessa"> = {
        id: uid(), commessa_id: id, nome, tipo,
        dimensione_bytes: Math.round((tipo === "PDF" ? 1_800_000 : 650_000) * (0.5 + rnd())),
        caricato_il: data, caricato_da_user_id: userId,
        binario_disponibile: true, storage_path: `${id}/${nome}`,
      };
      db.file_commessa.push(f);
      ev("upload", `File uploaded: ${nome}`, data, userId, undefined, { type: "file", id: f.id });
      return f;
    };

    const email = (kind: "pdf" | "prova_colore" | "caduta", data: string, userId: string, allegato?: Row<"file_commessa">) => {
      const tpl = db.email_template.find((x) => x.kind === kind)!;
      const autore = db.utenti.find((u) => u.id === userId)!;
      const destinatari = [cliente.email ?? `office@customer${spec.cliente}.example`];
      const e: Row<"email_inviate"> = {
        id: uid(), commessa_id: id, data, template_kind: kind,
        mittente: mailboxOf(userId), destinatari,
        cc: rnd() > 0.6 ? [`commerciale@${DEMO_DOMAIN}`] : [],
        oggetto: render(tpl.oggetto, c, cliente.nome, autore.nome),
        corpo: render(tpl.corpo, c, cliente.nome, autore.nome),
        allegato_nome: allegato?.nome ?? null, allegato_path: allegato?.storage_path ?? null,
        allegato_disponibile: Boolean(allegato), inviata_da_user_id: userId, stato: "inviata",
      };
      db.email_inviate.push(e);
      return e;
    };

    // 1) creation
    if (spec.manuale) {
      ev("creazione_manuale", "Job created manually", iso(creata), respProd.id, `Number ${numero} - ${cliente.nome}`);
    } else {
      ev("sincronizzazione_erp", "Job imported from the ERP", iso(creata), null, `Number ${numero} - ${cliente.nome}`);
    }

    // 2) assignment
    if (reached("assegnata") && assegnati.length) {
      const d = tick();
      const by = idx % 3 === 0 ? respGrafico : respProd;
      for (const g of assegnati) {
        db.commessa_assegnatari.push({ commessa_id: id, user_id: g.id, assegnato_il: d, assegnato_da_user_id: by.id });
      }
      c.termine_primo_pdf = iso(new Date(d).getTime() + 48 * HOUR);
      ev("assegnazione", "Assigned to designers", d, by.id, assegnati.map((g) => g.nome).join(", "));
    }

    // 3) claimed
    if (reached("in_lavorazione") && lead) {
      const d = tick();
      c.presa_in_carico_da_user_id = lead.id;
      c.presa_in_carico_il = d;
      ev("presa_in_carico", "Claimed", d, lead.id);
    }

    // 4) PDF rounds: the first `rifiuti` are sent back
    const rifiuti = spec.rifiuti ?? 0;
    const giri = reached("in_attesa_approvazione_pdf") ? rifiuti + 1 : rifiuti;
    for (let r = 1; r <= giri && lead; r++) {
      const nomePdf = `${codice}_PDF_${String(r).padStart(2, "0")}.pdf`;
      const f = file(nomePdf, "PDF", tick(), lead.id);
      const d = tick();
      const e = email("pdf", d, lead.id, f);
      ev("invio_pdf", "Send PDF — sent", d, lead.id, `To: ${e.destinatari.join(", ")}`, { type: "email", id: e.id });
      if (r <= rifiuti) {
        const dr = tick();
        ev("esito_pdf", "PDF needs changes", dr, respProd.id, "The customer asked for changes to the copy and the barcode.");
        c.revisioni_pdf = r;
        const minuti = spec.correzioni?.[r - 1];
        if (minuti) {
          const cr: Row<"correzioni"> = { id: uid(), commessa_id: id, user_id: lead.id, minuti, data: tick(), nota: "Changes requested by the customer" };
          db.correzioni.push(cr);
          ev("correzione_registrata", `Correction logged: ${minuti} min`, cr.data, lead.id, cr.nota ?? undefined, { type: "correzione", id: cr.id });
        }
      }
    }
    // extra corrections (beyond the PDF rounds) to trigger the ALR-01 alert
    (spec.correzioni ?? []).slice(rifiuti).forEach((minuti) => {
      if (!lead) return;
      const cr: Row<"correzioni"> = { id: uid(), commessa_id: id, user_id: lead.id, minuti, data: tick(), nota: "Colour touch-ups requested by the customer" };
      db.correzioni.push(cr);
      ev("correzione_registrata", `Correction logged: ${minuti} min`, cr.data, lead.id, cr.nota ?? undefined, { type: "correzione", id: cr.id });
    });

    // 5) PDF approved
    if (reached("in_attesa_prova_colore") && lead) {
      ev("esito_pdf", "PDF approved by the customer", tick(), respProd.id);
    }

    // 6) colour proof
    const prova = spec.prova;
    if (prova && lead) {
      if (prova === "spedita_approvata") {
        const d = tick();
        const e = email("prova_colore", d, lead.id);
        ev("invio_prova_colore", "Send colour proof — sent", d, lead.id, `To: ${e.destinatari.join(", ")}`, { type: "email", id: e.id });
        if (spec.wetransfer) ev("wetransfer", "WeTransfer delivery logged", tick(), lead.id, "High-resolution artwork sent to the printer");
      }
      c.esito_prova_colore = prova;
      ev("esito_prova_colore", `Colour proof: ${prova === "non_serve" ? "Not required" : prova === "da_rifare" ? "To be redone" : "Sent and approved"}`, tick(), respProd.id);
    }

    // 7) press proof
    if (reached("in_attesa_approvazione_caduta") && lead) {
      const f = file(`${codice}_press_proof.jpg`, "JPEG", tick(), lead.id);
      const d = tick();
      const e = email("caduta", d, lead.id, f);
      ev("invio_caduta", "Send press proof — sent", d, lead.id, `To: ${e.destinatari.join(", ")}`, { type: "email", id: e.id });
    }
    if (spec.esitoCaduta && lead) {
      c.esito_caduta = spec.esitoCaduta;
      ev("esito_caduta", "Press proof: Approved", tick(), respProd.id);
    }

    // 8) plates (possibly through an override)
    if (reached("in_produzione_matrice")) {
      const d = tick();
      if (spec.forzata) {
        const nf: Row<"note_forzatura"> = {
          id: uid(), commessa_id: id, step_saltato: "caduta_macchina", stato_target: "in_produzione_matrice",
          nota: "Customer emergency: press proof approved over the phone, written confirmation to follow.",
          data: d, user_id: respProd.id,
        };
        db.note_forzatura.push(nf);
        ev("forzatura", "Override to Plate production", d, respProd.id, nf.nota, { type: "forzatura", id: nf.id });
      } else {
        ev("esito_caduta", "Press proof approved, plate production started", d, respProd.id);
      }
    }

    // 9) shipping
    if (reached("spedito")) {
      const d = tick();
      c.spedita_il = d;
      ev("spedizione", "Job shipped", d, respProd.id, `Courier — ${stampatore.nome}`);
    }

    // active hold
    if (spec.sospesa) {
      const d = tick();
      const s: Row<"sospensioni"> = {
        id: uid(), commessa_id: id, motivo: spec.sospesa.motivo, nota: spec.sospesa.nota,
        aperta_il: d, aperta_da_user_id: respProd.id, chiusa_il: null, chiusa_da_user_id: null,
      };
      db.sospensioni.push(s);
      c.sospensione_attiva_id = s.id;
      ev("sospensione", "On hold", d, respProd.id, spec.sospesa.nota, { type: "sospensione", id: s.id });
    }

    if (spec.noteInterne) ev("nota_interna", "Internal note", tick(), respGrafico.id, spec.noteInterne);

    c.aggiornata_il = iso(t);
    db.commesse.push(c);
  });

  // old files: binary removed by retention (30 days after shipping)
  for (const c of db.commesse) {
    if (c.spedita_il && nowMs - new Date(c.spedita_il).getTime() > 30 * DAY) {
      for (const f of db.file_commessa) if (f.commessa_id === c.id) f.binario_disponibile = false;
      for (const e of db.email_inviate) if (e.commessa_id === c.id) e.allegato_disponibile = false;
    }
  }

  return db;
}
